const COL = {
  rd: '#D93A2F', or: '#F08A24', ye: '#F5C518', gr: '#3FA34D', bl: '#3B82D6', nb: '#2C4A8A', sk: '#8EC5EE', pu: '#7B4FB0',
  pk: '#E8799F', br: '#8A5A3B', tn: '#C9A26D', bf: '#E6CFA3', cr: '#F4EAD2', wh: '#FBFBF8', gy: '#8D949E', lg: '#C9CED6',
  dg: '#4A5058', bk: '#262A30', rf: '#B8532B', ol: '#8C9A3C', tl: '#1FA8A0', gd: '#D9A21B', cp: '#B3652E',
};

function parseCost(s) {
  if (!s || s === '-') return { n: [], or: false };
  const or = s.includes('/');
  const n = [];
  for (const part of or ? s.split('/') : [s]) {
    const re = /(\d?)([isfurw])/g; let m;
    while ((m = re.exec(part))) for (let k = 0; k < (+m[1] || 1); k++) n.push(m[2]);
  }
  return { n, or };
}
function parseEffect(s) {
  const [k, ...a] = s.split(',');
  return [k, ...a.map((x) => (/^-?\d+$/.test(x) ? +x : x))];
}
function parsePower(s) {
  if (!s || s === '-') return null;
  const c = s[0], body = s.slice(2);
  if (c !== 'p') return { c, e: parseEffect(body) };
  const [tr, e] = body.split('>');
  const [t, ta] = tr.split(',');
  return { c, tr: t, ta: ta || '', e: parseEffect(e) };
}
const COLOUR_RE = /(Black|White|Red|Blue|Green|Yellow|Scarlet|Purple|Golden|Gray|Brown|Pink|Rufous|Rusty|Indigo|Cerulean|Ruby|Snow|Painted|Rose|Lazuli|Harlequin)/;
const PERSON_RE = /[a-z]'s /;
const PLACE_RE = /(American|Eastern|Western|Northern|Mountain|California|Canada|Carolina|Louisiana|Baltimore|Caspian|Tundra|Prairie|Cactus|Sandwich|Mexican)/;
const BODY_RE = /(headed|throat|breast|bill|crown|wing|tail|belly|rump|eye|back|foot|neck|cheek|shoulder|cap|crest|face|leg)/i;

export const BIRDS = SRC.trim().split('\n').map((line, id) => {
  const [name, hab, cost, nest, pts, ws, fam, cols, power] = line.split('|');
  const c = cols.split(',').map((x) => COL[x] || x);
  const b = {
    id, name, hab: [...hab].map((h) => HAB_KEY.indexOf(h)), cost: parseCost(cost), nest: nest[0], eggs: +nest.slice(1), pts: +pts, ws: +ws,
    fam, col: c, pw: parsePower(power),
  };
  b.diet = [...new Set(b.cost.n)];
  b.tag = {
    colour: COLOUR_RE.test(name), person: PERSON_RE.test(name + ' '), place: PLACE_RE.test(name), body: BODY_RE.test(name),
    omni: b.cost.n.includes('w') || (b.cost.or && b.diet.length > 1),
    pred: !!b.pw && ['roll', 'hunt'].includes(b.pw.e[0]) && b.pw.c === 'b',
    flock: !!b.pw && ['tuckHand', 'tuckDeck'].includes(b.pw.e[0]),
    cacher: !!b.pw && ['cacheThis', 'feedCache', 'roll', 'tradeFCache'].includes(b.pw.e[0]),
    cheap: b.cost.n.length <= 1 && b.pts >= 3,
    multi: b.hab.length > 1,
    plain: !b.pw,
    pink: !!b.pw && b.pw.c === 'p',
  };
  return b;
});

