// ---- power text (our own wording)
const fl = (s) => (s === 'x' || s === 'w' ? 'any food' : [...s].map((c) => FOOD_NAME[c]).join(' or '));
const pl = (n, w) => `${n} ${w}${n === 1 ? '' : 's'}`;
function nestWord(f) { return f in NEST_NAME ? NEST_NAME[f] : ''; }
function filterWord(f) {
  if (!f || f === '*') return 'bird';
  if (f === 'row') return 'bird in this habitat';
  if (/[A-Z]/.test(f)) return `bird in your ${HAB_NAME[HAB_KEY.indexOf(f)]}`;
  return `${nestWord(f)}-nest bird`;
}
export function effectText(e) {
  const [k, a, b, c] = e;
  switch (k) {
    case 'gain': return `Gain ${b} ${fl(a)} from the supply.`;
    case 'feed': return a === 1 && !b ? 'Gain 1 food from the birdfeeder.' : b ? `Gain ${a} ${fl(b)} from the birdfeeder, if available.` : `Gain ${a} food from the birdfeeder.`;
    case 'draw': return `Draw ${pl(a, 'card')}.`;
    case 'layThis': return `Lay ${pl(a, 'egg')} on this bird.`;
    case 'layAny': return `Lay ${pl(a, 'egg')} on any ${a === 1 && b !== '*' ? '' : ''}${filterWord(b)}${a > 1 ? 's' : ''}.`;
    case 'layEach': return `Lay 1 egg on each ${filterWord(a)}.`;
    case 'cacheThis': return `Cache ${b} ${fl(a)} from the supply on this bird.`;
    case 'tuckHand': return b ? `Tuck up to ${pl(a, 'card')} from your hand behind this bird. Draw ${pl(b, 'card')} for each.` : `Tuck up to ${pl(a, 'card')} from your hand behind this bird.`;
    case 'tuckDeck': return `Tuck ${pl(a, 'card')} from the deck behind this bird.`;
    case 'eachFeed': return 'Every player gains 1 food from the birdfeeder, starting with you.';
    case 'eachDraw': return `Every player draws ${pl(a, 'card')} from the deck, starting with you.`;
    case 'eachLay': return `Every player lays 1 egg on a ${nestWord(a)}-nest bird. You lay 1 more.`;
    case 'resetFeeder': return `Re-roll the birdfeeder, then gain ${a} from it.`.replace('gain 1 from', 'gain 1 food from');
    case 'roll': return `Roll the dice outside the birdfeeder. If any show ${fl(a)}, cache 1 ${fl(a)} on this bird.`;
    case 'hunt': return `Peek at the top card of the deck. If its wingspan is under ${a} cm, tuck it behind this bird. Otherwise discard it.`;
    case 'tradeCF': return `Discard 1 card from your hand to gain 1 ${fl(a)}.`;
    case 'tradeEF': return `Discard 1 egg from any bird to gain ${b} ${fl(a)}.`;
    case 'tradeFE': return `Discard 1 ${fl(a)} to lay ${pl(b, 'egg')} on any bird.`;
    case 'tradeFCache': return `Discard 1 ${fl(a)} to cache ${b} ${fl(a)} on this bird.`;
    case 'feedCache': return `Take a ${fl(a)} die from the birdfeeder and cache it on this bird.`;
    case 'drawDiscard': return `Draw ${pl(a, 'card')}, then discard 1 card from your hand at the end of your turn.`;
    case 'bonus': return 'Draw 2 bonus cards and keep 1.';
    case 'playSecond': return `Play a second bird in your ${HAB_NAME[HAB_KEY.indexOf(a)]}. Pay its cost.`;
    case 'fewest': return `Player(s) with the fewest birds in their ${HAB_NAME[HAB_KEY.indexOf(a)]} ${b === 'draw' ? 'draw' : 'gain'} ${c}${b === 'draw' ? ' card' + (c === 1 ? '' : 's') : ''}.`;
    case 'repeat': return 'Repeat the brown power of another bird in this habitat.';
    default: return k;
  }
}
const lc = (s) => s[0].toLowerCase() + s.slice(1);
export function powerText(b) {
  const p = b.pw;
  if (!p) return '';
  if (p.c === 'w') return effectText(p.e);
  if (p.c === 'b') return effectText(p.e);
  const t = p.tr, a = p.ta;
  let when = 'When another player does something, ';
  if (t === 'play') when = a === '*' ? 'When another player plays a bird, ' : /[A-Z]/.test(a) ? `When another player plays a bird in their ${HAB_NAME[HAB_KEY.indexOf(a)]}, ` : `When another player plays a ${nestWord(a)}-nest bird, `;
  else if (t === 'lay') when = 'When another player takes the lay eggs action, ';
  else if (t === 'feed') when = a && a !== '*' ? `When another player takes ${fl(a)} with the gain food action, ` : 'When another player takes the gain food action, ';
  else if (t === 'draw') when = 'When another player takes the draw cards action, ';
  else if (t === 'pred') when = 'When another player\'s predator succeeds, ';
  return when + lc(effectText(p.e));
}
export const POWER_LABEL = { w: 'When played', b: 'When activated', p: 'Once between turns' };
